import json
import re
from docx import Document

# Load employee data
with open('/root/employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template document
doc = Document('/root/offer_letter_template.docx')

def clean_paragraph_text(paragraph, old_text, new_text):
    """Replace text in a paragraph while preserving formatting when possible"""
    full_text = paragraph.text
    if old_text in full_text:
        new_full_text = full_text.replace(old_text, new_text)
        # Clear all runs and set new text
        for run in paragraph.runs:
            run.text = ''
        if paragraph.runs:
            paragraph.runs[0].text = new_full_text
        else:
            paragraph.add_run(new_full_text)
        return True
    return False

def replace_placeholders_in_paragraph(paragraph, data):
    """Replace placeholders in a paragraph, handling cases where placeholders span multiple runs"""
    # First, get the full text
    full_text = paragraph.text

    # Check if there are any placeholders to replace
    has_replacements = False
    for key in data.keys():
        placeholder = f"{{{{{key}}}}}"
        if placeholder in full_text:
            has_replacements = True
            full_text = full_text.replace(placeholder, str(data[key]))

    # If replacements were made, update the paragraph
    if has_replacements:
        # Clear all runs
        for run in paragraph.runs:
            run.text = ''
        # Set the text in the first run
        if paragraph.runs:
            paragraph.runs[0].text = full_text
        else:
            paragraph.add_run(full_text)

def process_conditional_sections(doc, data):
    """Process conditional sections based on RELOCATION_PACKAGE"""
    keep_relocation = data.get('RELOCATION_PACKAGE', '').lower() == 'yes'

    # First pass: remove conditional markers
    for paragraph in doc.paragraphs:
        text = paragraph.text

        # Remove IF_RELOCATION marker
        if '{{IF_RELOCATION}}' in text:
            clean_paragraph_text(paragraph, '{{IF_RELOCATION}}', '')

        # Remove END_IF_RELOCATION marker
        if '{{END_IF_RELOCATION}}' in text:
            clean_paragraph_text(paragraph, '{{END_IF_RELOCATION}}', '')

    # Second pass: if not keeping relocation, remove the content between markers
    if not keep_relocation:
        paragraphs_to_remove = []
        inside_conditional = False

        # Need to re-check after cleaning markers
        # We'll look for specific text patterns that indicate relocation content
        for paragraph in doc.paragraphs:
            text = paragraph.text.lower()

            # Detect start of relocation section
            if 'relocation assistance' in text or 'relocation package' in text:
                inside_conditional = True

            # Track paragraphs in the relocation section
            if inside_conditional:
                paragraphs_to_remove.append(paragraph)

                # Check if this is likely the end of the section
                # (empty paragraph or start of new section)
                if not text.strip() or 'benefits' in text or 'paid time off' in text:
                    inside_conditional = False

        # Remove the identified paragraphs
        for paragraph in paragraphs_to_remove:
            p_element = paragraph._element
            p_element.getparent().remove(p_element)

# Process conditional sections first
process_conditional_sections(doc, data)

# Replace placeholders in all paragraphs
for paragraph in doc.paragraphs:
    replace_placeholders_in_paragraph(paragraph, data)

# Replace placeholders in tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                replace_placeholders_in_paragraph(paragraph, data)

